node -e "
const db = require('better-sqlite3')('/workspace/world.db');
const crypto = require('crypto');

const reminderId = crypto.randomUUID();
const content = 'Aurora Smart Desk Lamp Pro (PROD-73FAB4) — Price: \$88.00 | In Stock: Yes (24 units) | Warranty: 12 months | Return Window: 30 days (0% restocking fee)';
const creationTimestamp = new Date('2026-09-08T10:00:00').getTime() / 1000;  // current world time
const reminderTimestamp = new Date('2026-09-09T10:00:00').getTime() / 1000;  // tomorrow 10 AM

db.prepare(\`
  INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at)
  VALUES (?, ?, ?, ?, NULL, NULL, '2026-09-08T10:00:00')
\`).run(reminderId, content, creationTimestamp, reminderTimestamp);

console.log('Reminder created successfully!');
console.log('Reminder ID:', reminderId);

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('\nSaved reminder:', JSON.stringify(row, null, 2));
"
